-- 2026-11-13 A2-2.2.3 “一、进制转换与二进制运算”：OCR 符号修复，0–F 对应关系改为表格
begin;
create temp table _kba223(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kba223 values (71, $kba223$[{"t":"list","id":"a2-2-2-3-b1","imp":"core","items":["1、==操作系统主要功能==","==（1）多任务与处理器管理（进程管理）：CPU 资源分配。==","==（2）文件管理：对外存的管理，主要是创建（或保存）文件而分配存储空间，为删除文件而回收空间，对空闲空间进行分配 。通常采用==@@文件目录@@==来组织和管理外存中的信息。==","==（3）存储管理：对内存的管理，虚拟内存=物理内存+硬盘的虚拟接口。==","==（4）设备管理：对所有硬件设备管理，驱动程序是操作系统和硬件之间的接口。==","2、多任务与处理器管理","（1）前台任务∶能接受用户输入（击键或单击鼠标）的窗口只能有一个，称为活动窗口，它所对应的任务称为前台任务。前台任务只能有 1 个。","（2）并发多任务：允许计算机同时执行多个任务，任务是并发执行的，无论是前台任务，还是后台任务，都可以分配到CPU 资源。","（3）多任务实现的原理是∶操作系统将 CPU 时间划分为许多小时间片，轮流为多个程序服务。多个任务宏观上同时运行，微观上轮流运行。多任务处理并不一定需要多核 CPU 的硬件支撑。","（4）多任务的目的∶提高 CPU 的利用率，提高用户的工作效率。","（6）==现在流行的Windows、Linux、Android、IOS、HarmonyOS 都支持多任务处理==","3、==文件管理==：","（1）==文件的概念。 文件是存储在外存储器中的一组相关信息的集合。==","（2）文件名的命名原则。","^^①、文件名的组成∶主文件名.扩展名。主文件名不可以省略，扩展名可以省略。^^","^^②、主文件名中不可以出现\"、、?、*、\\、/、、<、>。^^","^^③、不可以使用系统保留的关键字 CON、PRN。^^","^^④、文件名最多有 255 个字符（中文或西文字符）。^^","^^⑤、Windows 中文件名不区分大小写。^^","^^⑥、文件名中可以使用空格，文件名开头不保留空格。^^","^^⑦、应用程序扩展名：.exe(Windows 中)、.app（iOS）、.apk（安卓）^^","^^⑧、常见文件扩展名：^^"],"title":"","ordered":false},{"t":"table","id":"a2-2-2-3-b2","imp":"important","rows":[["^^文件文件^^","^^.txt^^","^^声音文件^^","^^.wav,.min,.voc,mp3^^"],["^^Word 文件^^","^^.doc、.docx^^","^^图形、图像文件^^","^^.bmp,.pcx,.tif,.wmf,jpg,.png.,git^^"],["^^Excel 文件^^","^^.els.elsx^^","^^动画/视频文件^^","^^.flc,.fli,avi,mp4,.flv.mpg^^"],["^^PPT 文件^^","^^.ppt,pptx^^","^^网页文件^^","^^.html,.htm^^"]],"title":"","headers":["^^文件类型^^","^^文件扩展名^^","^^文件类型^^","^^文件扩展名^^"]},{"t":"list","id":"a2-2-2-3-b3","imp":"core","items":["（3）文件的组成。","①、文件由文件说明信息和文件内容两部分组成。","②、文件说明信息存放在文件的目录中。","③、文件的内容存放在磁盘的数据区中。","（4）Windows 文件目录采用多层次树状结构。","（5）==操作系统的文件管理是指在外存中为创建文件或保存文件而分配外存空间，除文件而回收空间，并对空闲空间进行管理。==","4、==存储管理==","（1）内存储器空间划分为2 个部分：系统区和用户区，用户区用来存放正在运行的应用程序","（2）==操作系统一般都采用虚拟存储器技术（也称虚拟内存技术，简称虚存）进行存储管理。==","（3）虚拟存储器 =物理内存 ＋硬盘上的虚拟内存。","（4）虚拟存储器大小受到外存空间及 CPU 地址表示范围的限制。","（5）在 Windows 中，用户可设置虚拟内存位于哪个硬盘逻辑盘上及其容量。每个程序的虚存空间最大可达到4GB。","（6）内存页面调度算法（LRU，最近最少使用）∶在每次调换时，找到最近最少使用的那个页面调出内存。","（7）在Windows 操作系统上虚拟内存文件位于系统盘的系统根目录下的 pagefile.sys。","5、==设备管理==","（1）操作系统中的\"设备管理\"负责对用户或者应用程序的IO 操作进行统一管理","（2）==设备管理通过驱动程序屏蔽和抽象了各种物理I/O 设备的硬件操作细节。驱序程序是操作系统和硬件之间的接口。==","6、==软件基础与数制、多媒体、网络知识汇总==：","一、==进制转换与二进制运算==","^^二进制转八进制：每 3 位一组（8 = 2³）；转十六进制：每 4 位一组（16 = 2⁴）。^^","对应关系如下："],"title":"","ordered":false},{"t":"table","id":"a2-2-2-3-t1","imp":"normal","title":"","headers":["数码","3 位二进制（八进制）","4 位二进制（十六进制）"],"rows":[["0","000","0000"],["1","001","0001"],["2","010","0010"],["3","011","0011"],["4","100","0100"],["5","101","0101"],["6","110","0110"],["7","111","0111"],["8","—","1000"],["9","—","1001"],["A","—","1010"],["B","—","1011"],["C","—","1100"],["D","—","1101"],["E","—","1110"],["F","—","1111"]]},{"t":"list","id":"a2-2-2-3-b3b","imp":"core","items":["二进制算术运算包括==加、减、乘、除==。","7、==文件、文件属性与文件管理==：文件是一组相关信息的集合，它存储在软盘、硬盘、光盘等外存储器上。Windows 系统中允许使用长文件名，最长可达 255 个字符。 文件说明信息包括：文件名、文件类型、文件物理位置、文件长度、文件时间（创建时间、最近修改时间、最近访问时间等）、文件创建者、文件属性等。 文件属性用于==将文件标注为系统文件、隐藏文件、存档文件或只读文件==。 文件目录的作用：通过文件名可以快速方便地获取文件的说明信息；提高文件的检索速度；允许文件在不同的目录中使用相同的名字；允许多个用户共享一个文件。","8、==时间片轮转与虚拟内存==：^^CPU 管理^^：==时间片轮转使多个任务同时工作==。其意义是把 CPU 的工作时间分成若干个时间片，分别执行各个任务。 虚拟内存就是把硬盘上暂时不用的空间当作内存使用。虚拟存储系统能够为用户提供一个容量很大的虚拟空间，其大小受到外存容量和 CPU 地址表示范围的限制。操作系统中，虚拟存储器容量大于实际内存。虚拟内存的大小可以由用户自己设定。 虚拟存储器采用的页面调度算法：随机算法、先进先出算法、近期最少使用算法和最优算法。","9、==处理机管理==：操作系统管理的硬件资源包括 ==CPU、存储器、I/O 设备以及网络通信设备==，软件资源包括程序和资料。操作系统不负责硬件与软件的转换。 处理机管理的特点：宏观上多个任务同时执行，微观上单一执行，让 CPU 轮流为所有任务服务。CPU 的管理方法有按时间片轮转和按优先级调度两种。多个用户同时与系统交互时，要把 CPU 时间划分为“时间片”，轮流为不同的用户程序服务，多个用户共享 CPU 的操作系统称为多任务分时操作系统。Windows 操作系统在任一时刻只有一个任务正在被执行。","10、==打印机的安装、设置与管理==：打印机是常见的输出设备，用户可以用它打印文档、图片等。 要在 Windows XP 中使用打印机，必须先将其安装到系统中。这里的“安装”主要是指==装入打印机驱动程序==，以使系统正确地识别和管理打印机。打印机按所处的地理位置划分，可分为本地打印机和网络打印机，其安装方法类似。 在开始安装之前，应了解打印机的生产厂商和类型，并使打印机与计算机正确连接。安装步骤如下：","（1）==将打印机连接到计算机==，打开打印机电源。","11、==文件与文件目录管理==：==文件是存储在辅助存储器中的一组相关信息的集合==。每个文件包含本身的内容（程序代码和数据，保存在磁盘的数据区）和说明信息。 文件名由主文件名和扩展名组成：","- ==不同扩展名的数据文件其内部格式不同==，大多数数据文件在不同操作系统中是通用的。","- ==文件名可以长达 255 个字符==；不可使用的字符有 9 个：/、\\、:、*、?、\"、<、>、|。 说明信息包括文件主名、扩展名、文件在存储中的位置、文件大小、创建时间、修改时间以及文件属性。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-2-3-b4","imp":"core","kind":"tip","text":"操作系统五大管理核心：==处理器管理（进程调度与生命周期控制）、存储管理（虚存分配与回收）、文件管理（按名存取与树状目录）、设备管理（缓冲技术与设备独立性）、作业管理与用户接口（命令行与图形界面）==。","title":"考向复习提示：操作系统五大管理职能概览"},{"t":"callout","id":"a2-2-2-3-b5","imp":"core","kind":"trap","text":"进程的三大基本状态：==就绪态（具备运行条件，仅缺 CPU）、运行态（正在 CPU 上执行）、阻塞态/等待态（等待某一外部事件如 I/O 完成，即使给 CPU 也无法运行）==；陷阱注意：==阻塞态不能直接跃迁到运行态==，事件完成后必须先进入就绪态等待调度，运行态分配的时间片用完进入就绪态而非阻塞态！","title":"高频易错陷阱：进程三态转换模型考点"}]$kba223$::jsonb, $kba223se$A2-2.2.3 操作系统的基本功能。 1、操作系统主要功能 （1）多任务与处理器管理（进程管理）：CPU 资源分配。 （2）文件管理：对外存的管理，主要是创建（或保存）文件而分配存储空间，为删除文件而回收空间，对空闲空间进行分配 。通常采用文件目录来组织和管理外存中的信息。 （3）存储管理：对内存的管理，虚拟内存=物理内存+硬盘的虚拟接口。 （4）设备管理：对所有硬件设备管理，驱动程序是操作系统和硬件之间的接口。 2、多任务与处理器管理 （1）前台任务∶能接受用户输入（击键或单击鼠标）的窗口只能有一个，称为活动窗口，它所对应的任务称为前台任务。前台任务只能有 1 个。 （2）并发多任务：允许计算机同时执行多个任务，任务是并发执行的，无论是前台任务，还是后台任务，都可以分配到CPU 资源。 （3）多任务实现的原理是∶操作系统将 CPU 时间划分为许多小时间片，轮流为多个程序服务。多个任务宏观上同时运行，微观上轮流运行。多任务处理并不一定需要多核 CPU 的硬件支撑。 （4）多任务的目的∶提高 CPU 的利用率，提高用户的工作效率。 （6）现在流行的Windows、Linux、Android、IOS、HarmonyOS 都支持多任务处理 3、文件管理： （1）文件的概念。 文件是存储在外存储器中的一组相关信息的集合。 （2）文件名的命名原则。 ①、文件名的组成∶主文件名.扩展名。主文件名不可以省略，扩展名可以省略。 ②、主文件名中不可以出现"、、?、*、\、/、、。 ③、不可以使用系统保留的关键字 CON、PRN。 ④、文件名最多有 255 个字符（中文或西文字符）。 ⑤、Windows 中文件名不区分大小写。 ⑥、文件名中可以使用空格，文件名开头不保留空格。 ⑦、应用程序扩展名：.exe(Windows 中)、.app（iOS）、.apk（安卓） ⑧、常见文件扩展名： 文件文件 .txt 声音文件 .wav,.min,.voc,mp3 Word 文件 .doc、.docx 图形、图像文件 .bmp,.pcx,.tif,.wmf,jpg,.png.,git Excel 文件 .els.elsx 动画/视频文件 .flc,.fli,avi,mp4,.flv.mpg PPT 文件 .ppt,pptx 网页文件 .html,.htm （3）文件的组成。 ①、文件由文件说明信息和文件内容两部分组成。 ②、文件说明信息存放在文件的目录中。 ③、文件的内容存放在磁盘的数据区中。 （4）Windows 文件目录采用多层次树状结构。 （5）操作系统的文件管理是指在外存中为创建文件或保存文件而分配外存空间，除文件而回收空间，并对空闲空间进行管理。 4、存储管理 （1）内存储器空间划分为2 个部分：系统区和用户区，用户区用来存放正在运行的应用程序 （2）操作系统一般都采用虚拟存储器技术（也称虚拟内存技术，简称虚存）进行存储管理。 （3）虚拟存储器 =物理内存 ＋硬盘上的虚拟内存。 （4）虚拟存储器大小受到外存空间及 CPU 地址表示范围的限制。 （5）在 Windows 中，用户可设置虚拟内存位于哪个硬盘逻辑盘上及其容量。每个程序的虚存空间最大可达到4GB。 （6）内存页面调度算法（LRU，最近最少使用）∶在每次调换时，找到最近最少使用的那个页面调出内存。 （7）在Windows 操作系统上虚拟内存文件位于系统盘的系统根目录下的 pagefile.sys。 5、设备管理 （1）操作系统中的"设备管理"负责对用户或者应用程序的IO 操作进行统一管理 （2）设备管理通过驱动程序屏蔽和抽象了各种物理I/O 设备的硬件操作细节。驱序程序是操作系统和硬件之间的接口。 6、软件基础与数制、多媒体、网络知识汇总： 一、进制转换与二进制运算 二进制转八进制：每 3 位一组（8 = 2³）；转十六进制：每 4 位一组（16 = 2⁴）。 对应关系如下： 0 000 0000 1 001 0001 2 010 0010 3 011 0011 4 100 0100 5 101 0101 6 110 0110 7 111 0111 8 — 1000 9 — 1001 A — 1010 B — 1011 C — 1100 D — 1101 E — 1110 F — 1111 二进制算术运算包括加、减、乘、除。 7、文件、文件属性与文件管理：文件是一组相关信息的集合，它存储在软盘、硬盘、光盘等外存储器上。Windows 系统中允许使用长文件名，最长可达 255 个字符。 文件说明信息包括：文件名、文件类型、文件物理位置、文件长度、文件时间（创建时间、最近修改时间、最近访问时间等）、文件创建者、文件属性等。 文件属性用于将文件标注为系统文件、隐藏文件、存档文件或只读文件。 文件目录的作用：通过文件名可以快速方便地获取文件的说明信息；提高文件的检索速度；允许文件在不同的目录中使用相同的名字；允许多个用户共享一个文件。 8、时间片轮转与虚拟内存：CPU 管理：时间片轮转使多个任务同时工作。其意义是把 CPU 的工作时间分成若干个时间片，分别执行各个任务。 虚拟内存就是把硬盘上暂时不用的空间当作内存使用。虚拟存储系统能够为用户提供一个容量很大的虚拟空间，其大小受到外存容量和 CPU 地址表示范围的限制。操作系统中，虚拟存储器容量大于实际内存。虚拟内存的大小可以由用户自己设定。 虚拟存储器采用的页面调度算法：随机算法、先进先出算法、近期最少使用算法和最优算法。 9、处理机管理：操作系统管理的硬件资源包括 CPU、存储器、I/O 设备以及网络通信设备，软件资源包括程序和资料。操作系统不负责硬件与软件的转换。 处理机管理的特点：宏观上多个任务同时执行，微观上单一执行，让 CPU 轮流为所有任务服务。CPU 的管理方法有按时间片轮转和按优先级调度两种。多个用户同时与系统交互时，要把 CPU 时间划分为“时间片”，轮流为不同的用户程序服务，多个用户共享 CPU 的操作系统称为多任务分时操作系统。Windows 操作系统在任一时刻只有一个任务正在被执行。 10、打印机的安装、设置与管理：打印机是常见的输出设备，用户可以用它打印文档、图片等。 要在 Windows XP 中使用打印机，必须先将其安装到系统中。这里的“安装”主要是指装入打印机驱动程序，以使系统正确地识别和管理打印机。打印机按所处的地理位置划分，可分为本地打印机和网络打印机，其安装方法类似。 在开始安装之前，应了解打印机的生产厂商和类型，并使打印机与计算机正确连接。安装步骤如下： （1）将打印机连接到计算机，打开打印机电源。 11、文件与文件目录管理：文件是存储在辅助存储器中的一组相关信息的集合。每个文件包含本身的内容（程序代码和数据，保存在磁盘的数据区）和说明信息。 文件名由主文件名和扩展名组成： - 不同扩展名的数据文件其内部格式不同，大多数数据文件在不同操作系统中是通用的。 - 文件名可以长达 255 个字符；不可使用的字符有 9 个：/、\、:、*、?、"、、|。 说明信息包括文件主名、扩展名、文件在存储中的位置、文件大小、创建时间、修改时间以及文件属性。 考向复习提示：操作系统五大管理职能概览 操作系统五大管理核心：处理器管理（进程调度与生命周期控制）、存储管理（虚存分配与回收）、文件管理（按名存取与树状目录）、设备管理（缓冲技术与设备独立性）、作业管理与用户接口（命令行与图形界面）。 高频易错陷阱：进程三态转换模型考点 进程的三大基本状态：就绪态（具备运行条件，仅缺 CPU）、运行态（正在 CPU 上执行）、阻塞态/等待态（等待某一外部事件如 I/O 完成，即使给 CPU 也无法运行）；陷阱注意：阻塞态不能直接跃迁到运行态，事件完成后必须先进入就绪态等待调度，运行态分配的时间片用完进入就绪态而非阻塞态！$kba223se$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kba223 loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
